// mund_keyframes/ hat jetzt zu jeder Grundstellung 5 echte Zwischenbilder
// (mund_NN_name__stufe_00..04.png -- fotografierte Bewegung ZUR Stellung hin,
// nicht irgendein generischer Gradient). Bisher sprang mundAnimation() hart
// zwischen Grundstellungen; jetzt spielt sie beim Wechsel zu einer neuen
// Zielstellung deren 5 Stufenbilder ab (+ das Zielbild selbst = 6 echte
// Frames), bevor sie dort haengen bleibt bis zum naechsten Taktschlag. Das
// macht aus dem Sprung eine Bewegung, OHNE die Silbentakt-Schaetzung selbst
// anzufassen (Koordinator woertlich: "Takt bleibt vorerst die bestehende
// Silbenschaetzung"). Abgespielt wird ueber mundSchritt() unten, angestossen
// von schleife(t) -- gleiches Bauprinzip wie koerperSchritt() oben, nur
// mit echten Einzelbildern statt Opacity-Crossfade (hier gibt es ja bereits
// fotografierte Zwischenschritte, kein Blending zweier Texturen noetig --
// genau das Problem, das bei der Halsnaht-Maske schiefging).
// ⚠️ Speicher: es werden NUR die Grundstellungen aus MUND_SPRECH_SET+MUND_RUHE
// UND deren je 5 Stufenbilder vorgeladen (9 Stellungen x 6 Bilder = 54),
// nicht alle 221 Dateien in mund_keyframes/.
function mundFrames(name){
  return [0,1,2,3,4].map(s => `/mund_keyframes/${name}__stufe_0${s}.png`)
    .concat([`/mund_keyframes/${name}.png`]);
}
const MUND_ALLE_STELLUNGEN = MUND_SPRECH_SET.concat([MUND_RUHE]);
for(const n of MUND_ALLE_STELLUNGEN){
  for(const src of mundFrames(n)){ const vorlade = new Image(); vorlade.src = src; }
}
let mundAktivFrames = null;
let mundAktivIndex = 0;
let mundLetzterFrameT = 0;
const MUND_FRAME_MS = 22; // 6 Frames in ~130ms Alt-Takt = ~21,7ms/Frame
function mundZielSetzen(name){
  mundAktivFrames = mundFrames(name);
  mundAktivIndex = 0;
  mundLetzterFrameT = 0; // sofort beim naechsten schleife()-Tick starten
}
function mundSchritt(jetzt){
  if(!mundAktivFrames) return;
  if(jetzt - mundLetzterFrameT < MUND_FRAME_MS) return;
  mundLetzterFrameT = jetzt;
  $("mund-effekt").src = mundAktivFrames[mundAktivIndex];
  mundAktivIndex++;
  if(mundAktivIndex >= mundAktivFrames.length) mundAktivFrames = null;
}
function mundAnimation(text){
  const grobeSilben = Math.max(3, Math.round((text || "").length / 2.6));
  const dauerMs = Math.min(9000, grobeSilben * 220);
  let letzte = -1;
  const iv = setInterval(() => {
    let i = Math.floor(Math.random() * MUND_SPRECH_SET.length);
    if(i === letzte) i = (i + 1) % MUND_SPRECH_SET.length; // nie zweimal dieselbe Stellung hintereinander
    letzte = i;
    mundZielSetzen(MUND_SPRECH_SET[i]);
  }, 130);
  setTimeout(() => { clearInterval(iv); mundZielSetzen(MUND_RUHE); }, dauerMs);
}

